mapper.select:
SELECT r.id AS id, r.request_no AS request_no, r.batch_id AS batch_id, r.batch_no AS batch_no, r.upstream_batch_id AS upstream_batch_id, r.upstream_batch_no AS upstream_batch_no, r.from_enterprise_id AS from_enterprise_id, r.from_enterprise_name AS from_enterprise_name, e.enterprise_type AS from_enterprise_type, de.item_value AS from_enterprise_type_name, r.to_enterprise_id AS to_enterprise_id, r.to_enterprise_name AS to_enterprise_name, r.handover_temp AS handover_temp, r.request_status AS request_status, rs.item_value AS request_status_name, r.request_time AS request_time FROM batch_confirm_request r LEFT JOIN node_enterprise e ON e.id = r.from_enterprise_id LEFT JOIN sys_dict_item de ON de.type_code = 'enterprise_type' AND de.item_code = CAST(e.enterprise_type AS CHAR) LEFT JOIN sys_dict_item rs ON rs.type_code = 'request_status' AND rs.item_code = CAST(r.request_status AS CHAR) WHERE r.to_enterprise_id = #{toEnterpriseId}
AND r.request_status = #{q.requestStatus}
AND r.from_enterprise_name LIKE CONCAT('%', #{q.downstreamEnterpriseName}, '%')
AND r.batch_no LIKE CONCAT('%', #{q.batchNo}, '%')
ORDER BY r.request_time ASC, r.id ASC
